param([string]$SavePath=(Join-Path $PSScriptRoot '../../.local-research/runtime/profile-20261102/Saves/apparel-stopped-b.rws'))
# Read-only extraction. No assembly execution or compressed map decoding.
$ErrorActionPreference='Stop'
$s=[xml](Get-Content -Raw -LiteralPath $SavePath)
function Num($node){if($null -eq $node){return 0.0};[double]::Parse($node.InnerText,[Globalization.CultureInfo]::InvariantCulture)}
function Stack($node){if($node.SelectSingleNode('stackCount')){return [int]$node.stackCount};1}
function Item($node){[ordered]@{id=[string]$node.id;def=[string]$node.def;stuff=[string]$node.stuff;quality=[string]$node.quality;health=[int]$node.health;count=(Stack $node);pos=[string]$node.pos;spawned_tick=[int]$node.spawnedTick;despawned_tick=[int]$node.despawnedTick}}
$p=$s.SelectSingleNode('//thing[id="Human961"]');$d=$p.SelectSingleNode('jobs/curDriver');$skill=$p.SelectSingleNode('skills/skills/li[def="Crafting"]')
$worker=[ordered]@{id=[string]$p.id;nick=[string]$p.name.nick;pos=[string]$p.pos;health_state_explicit=[string]$p.healthTracker.healthState;hediffs=@($p.SelectNodes('healthTracker/hediffSet/hediffs/li')|ForEach-Object{[ordered]@{def=[string]$_.def;severity=(Num $_.SelectSingleNode('severity'))}});crafting=[ordered]@{level=[int]$skill.level;xp_since_level=(Num $skill.SelectSingleNode('xpSinceLastLevel'))};worn=@($p.SelectNodes('apparel/wornApparel/innerList/li')|ForEach-Object{Item $_});forced_apparel=@($p.SelectNodes('outfits/overrideHandler/forcedAps/li')|ForEach-Object{$_.InnerText});last_apparel_wearout_tick=[int]$p.apparel.lastApparelWearoutTick;job=[ordered]@{def=[string]$p.jobs.curJob.def;target_a=[string]$p.jobs.curJob.targetA;target_b=[string]$p.jobs.curJob.targetB;bill=[string]$p.jobs.curJob.bill;count=[int]$p.jobs.curJob.count;driver=[string]$d.Class;toil_index=[int]$d.curToilIndex;start_tick=[int]$d.startTick;work_left=(Num $d.SelectSingleNode('workLeft'));bill_start_tick=[int]$d.billStartTick;ticks_spent_recipe=[int]$d.ticksSpentDoingRecipeWork};work_priority_values=@($p.SelectNodes('workSettings/priorities/vals/li')|ForEach-Object{[int]$_.InnerText})}
$cloth=@($s.SelectNodes('//*[def="Cloth" and id]')|ForEach-Object{[ordered]@{id=[string]$_.id;count=(Stack $_);health=[int]$_.health;pos=[string]$_.pos;parent=$_.ParentNode.Name;ingredient_of=if($_.ParentNode.Name -eq 'ingredients'){[string]$_.ParentNode.ParentNode.id}else{''};forbidden=([string]$_.forbidden -eq 'True')}}|Sort-Object {$_.id})
$benches=@($s.SelectNodes('//thing[def="HandTailoringBench"]')|ForEach-Object{[ordered]@{id=[string]$_.id;pos=[string]$_.pos;stuff=[string]$_.stuff;health=[int]$_.health;spawned_tick=[int]$_.spawnedTick;bills=@($_.SelectNodes('billStack/bills/li')|ForEach-Object{[ordered]@{recipe=[string]$_.recipe;repeat_mode=[string]$_.repeatMode;repeat_count=[int]$_.repeatCount;repeat_count_field_present=($null -ne $_.SelectSingleNode('repeatCount'));bound_uft=[string]$_.boundUft;allowed_materials=@($_.SelectNodes('ingredientFilter/allowedDefs/li')|ForEach-Object{$_.InnerText})}})}})
$unfinished=@($s.SelectNodes('//*[def="UnfinishedApparel" and id]')|ForEach-Object{[ordered]@{id=[string]$_.id;stuff=[string]$_.stuff;recipe=[string]$_.recipe;bill=[string]$_.bill;creator=[string]$_.creator;creator_name=[string]$_.creatorName;spawned_tick=[int]$_.spawnedTick;work_left=(Num $_.SelectSingleNode('workLeft'));ingredients=@($_.SelectNodes('ingredients/li')|ForEach-Object{[ordered]@{id=[string]$_.id;def=[string]$_.def;count=(Stack $_)}})}})
[ordered]@{file=(Split-Path -Leaf $SavePath);sha256=(Get-FileHash -LiteralPath $SavePath -Algorithm SHA256).Hash.ToLowerInvariant();bytes=(Get-Item -LiteralPath $SavePath).Length;version=$s.SelectSingleNode('//meta/gameVersion').InnerText;mods=@($s.SelectNodes('//meta/modIds/li')|ForEach-Object{$_.InnerText});tick=[int]$s.SelectSingleNode('//tickManager/ticksGame').InnerText;worker=$worker;ground_apparel=@($s.SelectNodes('//thing[starts-with(def,"Apparel_")]')|ForEach-Object{Item $_}|Sort-Object {$_.id});cloth=$cloth;cloth_total=[int](($cloth|Measure-Object -Property count -Sum).Sum);benches=$benches;unfinished=$unfinished;scope='Explicit XML only; omitted numeric values use zero defaults. RepeatCount presence retained. Worn items are read from apparel/wornApparel/innerList/li; forced references from outfits/overrideHandler. Work priority vector remains undecoded. No gameplay execution.'}|ConvertTo-Json -Depth 20
